249	    private static boolean isBlank(String value) {
250	        return value == null || value.isBlank();
251	    }
252	
253	    /**
254	     * Normalizes a street address into the canonical form stored on and returned for a newly
255	     * created owner. A {@code null} value becomes the empty string; otherwise surrounding
256	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space, the
257	     * text is upper-cased, and common street-type abbreviations are expanded on a whole-word
258	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The normalized
259	     * value is what gets persisted, echoed back, and used for every address comparison (household
260	     * duplicate detection and the shared household identifier).
261	     *
262	     * @param rawAddress the address value as supplied by the client
263	     * @return the normalized address (possibly empty, never {@code null})
264	     */
265	    private static String normalizeAddress(String rawAddress) {
266	        if (rawAddress == null) {
267	            return "";
268	        }
269	        String collapsed = rawAddress.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
270	        if (collapsed.isEmpty()) {
271	            return "";
272	        }
273	        String[] tokens = collapsed.split(" ");
274	        StringBuilder sb = new StringBuilder(collapsed.length());
275	        for (int i = 0; i < tokens.length; i++) {
276	            String token = tokens[i];
277	            switch (token) {
278	                case "ST" -> token = "STREET";
279	                case "RD" -> token = "ROAD";
280	                case "AVE" -> token = "AVENUE";
281	                default -> { }
282	            }
283	            if (i > 0) {
284	                sb.append(' ');
285	            }
286	            sb.append(token);
287	        }
288	        return sb.toString();
289	    }
290	
291	    /**
292	     * Builds the customer code assigned to a newly created owner. The code is formatted
293	     * {@code <LAST3>-<NNNN>} where {@code LAST3} is the upper-cased first three letters of
294	     * the owner's last name and {@code NNNN} is a global 4-digit zero-padded sequence equal
295	     * to one more than the current number of owners (e.g. {@code SMI-0007}).
296	     *
297	     * @param lastName the last name of the owner being created
298	     * @return the customer code to assign
299	     */
300	    private String nextCustomerCode(String lastName) {
301	        StringBuilder last3 = new StringBuilder();
302	        for (int i = 0; i < lastName.length() && last3.length() < 3; i++) {
303	            char c = lastName.charAt(i);
304	            if (Character.isLetter(c)) {
305	                last3.append(Character.toUpperCase(c));
306	            }
307	        }
308	        long sequence = this.clinicService.findAllOwners().size() + 1L;
309	        return String.format("%s-%04d", last3, sequence);
310	    }
311	
312	    /**
313	     * Normalizes a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value
314	     * already carrying a leading {@code '+'} keeps its country code; otherwise country code
315	     * {@code +61} is assumed and a single leading {@code '0'} is dropped from the national digits.
316	     * The result must carry a leading {@code '+'} followed by 8 to 15 digits.
317	     *
318	     * @param rawTelephone the telephone value as supplied by the client
319	     * @return the telephone in E.164 form (e.g. {@code +61412345678})
320	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
321	     */
322	    private static String normalizeTelephone(String rawTelephone) {
323	        if (rawTelephone == null) {
324	            throw new InvalidTelephoneException(rawTelephone);
325	        }
326	        String cleaned = rawTelephone.replaceAll("[\\s\\-()]", "");
327	        String e164;
328	        if (cleaned.startsWith("+")) {
329	            String digits = cleaned.substring(1);
330	            if (!digits.matches("[0-9]+")) {
331	                throw new InvalidTelephoneException(rawTelephone);
332	            }
333	            e164 = "+" + digits;
334	        } else {
335	            if (!cleaned.matches("[0-9]+")) {
336	                throw new InvalidTelephoneException(rawTelephone);
337	            }
338	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
339	            e164 = "+61" + national;
340	        }
341	        int digitCount = e164.length() - 1;
342	        if (digitCount < 8 || digitCount > 15) {
343	            throw new InvalidTelephoneException(rawTelephone);
344	        }
345	        return e164;
346	    }
347	
348	    /**
349	     * Determines whether any existing owner already uses the given E.164 telephone. Stored
350	     * telephones are themselves E.164, so the values are compared directly.
351	     *
352	     * @param e164Telephone the E.164 telephone of the owner being created
353	     * @return {@code true} if another owner already has the same E.164 telephone
354	     */
355	    private boolean isTelephoneInUse(String e164Telephone) {
356	        return this.clinicService.findAllOwners().stream()
357	            .map(Owner::getTelephone)
358	            .filter(existing -> existing != null)
359	            .anyMatch(e164Telephone::equals);
360	    }
361	
362	    /**
363	     * Determines whether any existing owner already shares a household with the owner being created,
364	     * i.e. has both the same last name and the same address. Both fields are compared
365	     * case-insensitively after collapsing runs of whitespace to a single space and trimming.
366	     *
367	     * @param lastName the last name of the owner being created
368	     * @param address the address of the owner being created
369	     * @return {@code true} if another owner already has the same last name and address
370	     */
371	    private boolean isHouseholdInUse(String lastName, String address) {
372	        String normalizedLastName = normalizeIdentity(lastName);
373	        String normalizedAddress = normalizeIdentity(address);
374	        return this.clinicService.findAllOwners().stream()
375	            .anyMatch(existing -> normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
376	                && normalizeIdentity(existing.getAddress()).equals(normalizedAddress));
377	    }
378	
379	    /**
380	     * Counts how many existing owners already share the given first name and last name with the
381	     * owner being created. Both names are compared case-insensitively (after trimming and
382	     * collapsing runs of whitespace). The count reflects the state before the new owner is
383	     * persisted, so a first, otherwise-unique owner yields {@code 0}.
384	     *
385	     * @param firstName the first name of the owner being created
386	     * @param lastName the last name of the owner being created
387	     * @return the number of existing owners sharing the same first and last name
388	     */
389	    private int namesakeCount(String firstName, String lastName) {
390	        String normalizedFirstName = normalizeIdentity(firstName);
391	        String normalizedLastName = normalizeIdentity(lastName);
392	        return (int) this.clinicService.findAllOwners().stream()
393	            .filter(existing -> normalizeIdentity(existing.getFirstName()).equals(normalizedFirstName)
394	                && normalizeIdentity(existing.getLastName()).equals(normalizedLastName))
395	            .count();
396	    }
397	
398	    /**
399	     * Assigns the owner being created to the household identified by the given last name and
400	     * address and returns the household's stable shared identifier. The identifier is derived
401	     * deterministically from the normalized last name and address, so every member of the same
402	     * household resolves to the same value regardless of creation order. Any existing member that
403	     * does not yet carry the identifier is back-filled so all household members share it.
404	     *
405	     * @param lastName the last name of the owner being created
406	     * @param address the address of the owner being created
407	     * @return the stable household identifier shared by all members of the household
408	     */
409	    private String joinHousehold(String lastName, String address) {
410	        String householdId = householdIdFor(lastName, address);
411	        String normalizedLastName = normalizeIdentity(lastName);
412	        String normalizedAddress = normalizeIdentity(address);
413	        for (Owner existing : this.clinicService.findAllOwners()) {
414	            if (normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
415	                && normalizeIdentity(existing.getAddress()).equals(normalizedAddress)
416	                && !householdId.equals(existing.getHouseholdId())) {
417	                existing.setHouseholdId(householdId);
418	                this.clinicService.saveOwner(existing);
419	            }
420	        }
421	        return householdId;
422	    }
423	
424	    /**
425	     * Derives the stable household identifier for a given last name and address. The value is the
426	     * first 16 upper-case hex characters of the SHA-256 digest of the normalized last name and
427	     * address, so it is stable across calls and identical for every member of the household.
428	     *
429	     * @param lastName the last name of the household
430	     * @param address the address of the household
431	     * @return the stable household identifier
432	     */
433	    private static String householdIdFor(String lastName, String address) {
434	        String key = normalizeIdentity(lastName) + "\n" + normalizeIdentity(address);
435	        try {
436	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
437	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
438	            StringBuilder sb = new StringBuilder(digest.length * 2);
439	            for (byte b : digest) {
440	                sb.append(String.format("%02x", b));
441	            }
442	            return sb.substring(0, 16).toUpperCase(java.util.Locale.ROOT);
443	        }
444	        catch (java.security.NoSuchAlgorithmException e) {
445	            throw new IllegalStateException("SHA-256 not available", e);
446	        }
447	    }
448	
449	    /**
450	     * Normalizes a text field for household-identity comparison: {@code null} becomes the empty
451	     * string, surrounding whitespace is trimmed, internal runs of whitespace are collapsed to a
452	     * single space, and the result is lower-cased.
453	     *
454	     * @param value the raw field value
455	     * @return the normalized value used for case-insensitive, whitespace-insensitive comparison
456	     */
457	    private static String normalizeIdentity(String value) {
458	        if (value == null) {
459	            return "";
460	        }
461	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
462	    }
463	}
